export const getAuthorizeSharedConnectionActionUrl = (
  organizationId: string,
  appId: string,
) => {
  return `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/apps/${encodeURIComponent(String(appId))}/shared-connection/authorize`;
};

/**
 * Start consent for one action of an app's shared account, where the app grants access action by action, and answer the address of the app's consent page, as authorizeConnectionAction does for a person's own. Only an administrator may authorize for the shared account. The address is never logged.
 * @summary Start consent for one action on an app's shared account
 */
export const authorizeSharedConnectionAction = async (
  organizationId: string,
  appId: string,
  authorizeActionRequest: AuthorizeActionRequest,
  headers: AuthorizeSharedConnectionActionHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<AuthorizationStart> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<AuthorizationStart>(
    getAuthorizeSharedConnectionActionUrl(organizationId, appId),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...headers,
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(authorizeActionRequest),
    },
  );
};

